      "qualitative_rationale_de": "Das Projekt erfährt mit 7 von 7 Stimmen eine sehr hohe, faktisch einstimmige Unterstützung. Die Stimmung in den Rückmeldungen ist klar positiv: Das Projekt wird als gut durchdacht und inklusiv wahrgenommen und als passend zu den Schwerpunkten Personenvielfalt sowie Kultur im öffentlichen Raum beschrieben. Besonders hervorgehoben werden die niederschwellige Zugänglichkeit durch mehrere Veranstaltungen und ein Budget, das als sinnvoll und direkt auf inklusive Massnahmen ausgerichtet beurteilt wird.",
      "qualitative_rationale_en": "The project receives very high, effectively unanimous support with 7 out of 7 votes. The overall sentiment in the feedback is clearly positive: the project is seen as well thought-out and inclusive, and as matching the priorities of diversity of people and culture in public space. Commenters particularly highlight the low-threshold accessibility through multiple events and a budget that is viewed as reasonable and directly focused on inclusive measures.",
      "unified_explanation_de": "Das Projekt 'Inklusive lauschig-Lesungen' wurde von allen 7 abstimmenden Personen unterstuetzt und als stimmig mit den Schwerpunkten Personenvielfalt und Kultur im oeffentlichen Raum erlebt. Besonders ueberzeugt hat, dass die Mittel direkt in konkrete inklusive Massnahmen fliessen und durch mehrere Veranstaltungen vielen Menschen einen niederschwelligen Zugang ermoeglichen.",
      "unified_explanation_en": "The project 'Inklusive lauschig-Lesungen' was supported by all 7 people who voted and was seen as a strong fit with the priorities of diversity and culture in public spaces. Voters were especially convinced that the budget flows directly into concrete inclusive measures and that multiple events make the project accessible to a wider group of people.",
