      "efficiency": 625.0,
      "mes_rho": 625.0,
      "qualitative_rationale_de": "Das Projekt 'ANTE' (056) stoesst mit 5 von 7 Stimmen auf eine sehr hohe, nahezu einhellige Zustimmung. Die quantitative Bewertung (Mittelwert 0.71) bestaetigt dieses insgesamt positive Bild. In den Kommentaren werden vor allem die starke Gemeinschaft durch Austausch, Kultur im oeffentlichen Raum, das Erfahren, Erleben, Anregen und Lernen sowie die Offenheit fuer unterschiedliche Personengruppen hervorgehoben. Besonders positiv betont werden die verbindende Kraft von Musik, das Angebot im Freien und das kleine, ueberschaubare Format, das auch fuer Menschen geeignet ist, die grosse Menschenmengen meiden. Zudem wird der bewusste Gegenakzent zu grossen Festivals und die Angemessenheit des Budgets gelobt. Vereinzelt gibt es Kritik, dass das Projekt sehr professionell wirkt und bereits viele Sponsoren hat, mit der Empfehlung, eine Unterstuetzung gegebenenfalls leicht zu reduzieren. Insgesamt ueberwiegt jedoch klar die starke Zustimmung und Wertschaetzung fuer das Projekt.",
      "qualitative_rationale_en": "The project 'ANTE' (056) enjoys very high, nearly unanimous support, with 5 out of 7 voters in favor. The quantitative rating (mean score 0.71) confirms this overall positive picture. Comments highlight the strong sense of community through exchange, culture in public space, opportunities to experience, learn and be inspired, and inclusivity for diverse groups of people. Particularly positive aspects include the unifying power of music, the outdoor setting, and the small, intimate scale, which makes it accessible for people who are uncomfortable in large crowds. The project is also praised for consciously positioning itself as a counterpoint to large festivals and for having an appropriate budget. There is some isolated criticism that the project appears very professional with many sponsors, along with a suggestion to reduce potential funding slightly. Overall, however, the strong approval and appreciation for the project clearly prevails.",
      "unified_explanation_de": "ANTE hat mit 5 von 7 Stimmen eine sehr starke Unterstützung in der Gruppe erhalten, weil die Menschen besonders die verbindende Kraft der Musik, den offenen Austausch und das kleine, überschaubare Festivalformat im Freien geschätzt haben. Trotz einzelner kritischer Stimmen zur Professionalität und Finanzierung konnte das Projekt viele überzeugen und wurde als kostengünstig, effizient und bewusstes Gegenmodell zu grossen Festivals gern vom MAS finanziert.",
      "unified_explanation_en": "ANTE received very strong support from the group with 5 out of 7 votes, as people especially appreciated the connecting power of music, the open exchange, and the small, manageable open-air festival format. Despite some critical remarks about its professional setup and funding, the project convinced many voters and, as a low-cost, efficient and deliberate counterpoint to large festivals, was happily funded by the MAS.",
