      "qualitative_rationale_de": "Das Projekt „15 Jahre Theater Ariane – wir feiern einen Begegnungsort“ stoesst mit 5 von 7 Stimmen auf eine sehr hohe, nahezu geschlossene Zustimmung. Die Kommentare betonen besonders den Begegnungs- und Austauschcharakter: Nach der Vorstellung kommen Schauspielende und Publikum ins Gespraech, was als bereichernd und ungewoehnlich positiv hervorgehoben wird. Inhaltlich wird die starke Gemeinschaft, der Mut zur Ueberraschung, das gemeinsame Erfahren und Lernen sowie Kultur fuer eine vielfaeltige Bevoelkerung gewuerdigt. Die Story wird als gut und neugierig machend beschrieben. Kritisch hinterfragt wird vor allem die Finanzplanung (fehlende Einnahmen, moeglicherweise Reduktion der Unterstuetzung um 20 %), insgesamt wird das Budget aber als plausibel und der beantragte Beitrag als anstaendig beurteilt. Insgesamt ist die Stimmung deutlich positiv mit sehr hoher inhaltlicher und gemeinschaftsbezogener Wertschaetzung bei leichten Bedenken zur Finanzierung.",
      "qualitative_rationale_en": "The project “15 Years of Theater Ariane – We Celebrate a Place of Encounter” receives very high, nearly unanimous support with 5 out of 7 votes. Comments particularly emphasize the value of encounter and exchange: after the performance, actors and audience engage in dialogue, which is seen as enriching and unusually positive. Substantively, the project is praised for fostering a strong sense of community, openness to surprise, shared experiences and learning, and culture that is accessible to a diverse population. The story is considered good and piques curiosity. Critical feedback focuses mainly on the financial plan (no apparent income, suggestion to reduce funding by 20%), while the overall budget is still viewed as plausible and the requested amount as reasonable. Overall, the sentiment is clearly positive, with very high appreciation of the content and community impact, alongside minor concerns about financing.",
      "unified_explanation_de": "Das Projekt „15 Jahre Theater Ariane – wir feiern einen Begegnungsort“ fand mit 5 von 7 Stimmen grossen Rückhalt in der Community, weil es Menschen nach der Vorstellung bewusst in den Austausch bringt und so eine starke, vielfältige Gemeinschaft fördert. Trotz einzelner offenen Fragen, etwa zu Einnahmen, konnte die Idee eines lebendigen Begegnungsortes viele überzeugen und wurde deshalb kostengünstig und wirkungsvoll durch MES ermöglicht.",
      "unified_explanation_en": "The project “15 Years of Theater Ariane – celebrating a place of encounter” received strong support from the community, with 5 out of 7 people backing it, because it brings actors and audience into conversation after the performance and fosters a strong, diverse community. Despite a few open questions, such as around potential income, the idea of a vibrant meeting place convinced many voters and was therefore realized in a cost‑efficient and impactful way through MES.",
