      "unified_explanation_en": "With 5 out of 9 votes, 'Brunnen gehn Winterthur' clearly resonated very well in this group, especially with its focus on exchange, diversity and strengthening community ties – even if not everyone fully agreed on how cultural the project is. Despite this strong backing, the project unfortunately could not be realised this time because the limited overall budget and other priorities did not allow for full funding.",
