      "qualitative_rationale_de": "Das Projekt 'Dialogplatzkonzerte 2027' stoesst mit 5 von 7 Stimmen auf eine sehr hohe, nahezu einstimmige Zustimmung. Die Gesamtbewertung ist positiv, auch wenn einzelne Kommentare auf Bedenken zur Verhaeltnismaessigkeit des Aufwands (insbesondere Aufbau, Abbau und Planung), zur Hoehe des Budgets sowie zur Unklarheit ueber die genaue Anzahl und Daten der Konzerte hinweisen. Zudem wird erwaehnt, dass bereits im Vorjahr eine Foerderung erfolgt ist. Insgesamt ist die grundsaetzliche Unterstuetzung stark, bei gleichzeitigem Wunsch nach Praezisierung der Planung und einer moeglichen Budgetanpassung.",
      "qualitative_rationale_en": "The project 'Dialogplatzkonzerte 2027' enjoys very high, nearly unanimous support, with 5 out of 7 voters in favor. Overall sentiment is clearly positive, although some comments raise concerns about whether the planned effort (especially setup, takedown, and planning time) is proportionate to the event, as well as about the overall budget and the unclear number and dates of the concerts. It is also noted that the project already received funding last year. In summary, support for the project is strong, while reviewers ask for clearer planning details and potentially an adjustment of the budget.",
      "unified_explanation_de": "Die Dialogplatzkonzerte 2027 fanden bei der Community grossen Anklang – die deutliche Mehrheit der Abstimmenden unterstützte das Projekt, auch wenn es noch offene Fragen zu Anzahl Konzerten, Aufwand und Planung gab. Trotz seiner vielen Unterstützerinnen und Unterstützer konnte das Projekt dieses Mal leider wegen des begrenzten Gesamtbudgets und anderer Prioritäten nicht realisiert werden.",
      "unified_explanation_en": "The Dialogplatz Concerts 2027 resonated strongly with the community – a clear majority of voters supported the project, even though there were still open questions about the number of concerts, the workload and the planning. Despite its many supporters, the project unfortunately could not be realized this time due to the limited total budget and other priorities.",
