      "qualitative_rationale_de": "Die Konzertreihe 'Zeitspuren' verzeichnet mit 4 von 7 Stimmen eine eher hohe Zustimmung. Quantitativ wird das Projekt damit mehrheitlich positiv beurteilt, auch wenn der durchschnittliche Score von 0.29 auf gewisse Vorbehalte hinweist. In den Kommentaren werden insbesondere das hohe Budget, die Kosten für Übernachtung und Verpflegung sowie die Position von Archiv-, Vermittlungs- und Folgeprojektkosten kritisch hinterfragt. Zudem gibt es Skepsis hinsichtlich der Einbindung ausländischer Künstlerinnen und Künstler, der eher älteren Zielgruppe und des Potenzials, neues Publikum zu gewinnen. Insgesamt überwiegt jedoch die grundsätzliche Unterstützung, während sich die Kritik vor allem auf Budgethöhe, Kostenstruktur und Reichweite des Publikums konzentriert.",
      "qualitative_rationale_en": "The concert series 'Zeitspuren' receives relatively strong support, with 4 out of 7 voters in favor. Quantitatively, the project is thus assessed mostly positively, even though the mean score of 0.29 indicates some reservations. The comments focus critically on the high overall budget, the costs for accommodation and catering, and the allocation for archive, outreach, and follow-up projects. There is also skepticism regarding the inclusion of foreign artists, the rather older target audience, and the project’s potential to attract new listeners. Overall, however, the basic level of support predominates, while criticism is mainly directed at the budget size, cost structure, and audience reach.",
      "unified_explanation_de": "Die Konzertreihe «Zeitspuren» hat mit 4 von 7 Stimmen einen beachtlichen Rückhalt gefunden und besonders mit ihrem umfangreichen Programm von 12 Konzerten Interesse geweckt, auch wenn es Fragen zu Budgethöhe, Ausgabenstruktur und Zielgruppe gab. Trotz dieser deutlichen Unterstützung konnte das Projekt wegen des begrenzten Gesamtbudgets und anderer Prioritäten dieses Mal leider nicht realisiert werden.",
