      "qualitative_rationale_de": "Die Zustimmung zum Projekt ist mit 3 von 7 Stimmen moderat. Inhaltlich wird positiv hervorgehoben, dass das Projekt gut an den Förderkompass anknüpft (Mut zur Überraschung; Erfahren, Erleben, Anregen und Lernen) und als Startrampe für Newcomer-Künstlerinnen und -Künstler verstanden werden kann. Auch das Budget wird als plausibel und der beantragte Betrag als nachvollziehbar beschrieben. Kritisch hinterfragt wird, inwiefern tatsächlich ein wertvoller Austausch stattfindet, da Feedback nicht automatisch Austausch bedeutet. Zudem wird die Formulierung „Das war wirklich schwach, hahaha“ bei einem bestimmten Gefühlszustand als potenziell verletzend beurteilt; es besteht Sorge, ob der Rahmen für Auftretende immer sicher und wertschätzend ist. Eine Stimme findet das Projekt eher zu professionell/teuer im Verhältnis zu den Eintritten und regt gegebenenfalls eine Reduktion der Unterstützung an.",
      "qualitative_rationale_en": "Support for the project is moderate, with 3 out of 7 votes. Substantively, it is viewed positively for aligning well with the funding compass (courage to surprise; experiencing, discovering, stimulating and learning) and for functioning as a launchpad for newcomer artists. The budget is seen as plausible and the requested amount as comprehensible. On the critical side, it is questioned to what extent the project truly enables meaningful exchange, since feedback is not automatically the same as dialogue. The phrasing “That was really weak, hahaha” for one emotional state is perceived as potentially hurtful; there are concerns about whether a consistently safe and appreciative environment is provided for performers. One comment also perceives the project as somewhat too professional/expensive relative to ticket income and suggests possibly reducing the level of support.",
      "unified_explanation_de": "Rampensau hat mit 3 von 7 Stimmen spürbare Unterstützung erhalten, insbesondere als mutige Startrampe für Newcomer-Künstler*innen, auch wenn einige Fragen zu Wertschätzung, Feedbackkultur und Kostenstruktur offenblieben. Trotz dieser klaren Resonanz in der Gruppe konnte das Projekt aufgrund des begrenzten Gesamtbudgets und anderer Prioritäten dieses Mal leider nicht realisiert werden.",
      "unified_explanation_en": "Rampensau received tangible support from 3 out of 7 voters, especially as a bold launchpad for newcomer artists, even though some questions about appreciation, feedback culture, and cost structure remained. Despite this clear resonance in the group, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
