      "qualitative_rationale_de": "Die Zustimmung zum Projekt 'Mitmachen' (092) ist mit 3 von 7 Stimmen moderat. Der mittlere Score von -0.14 sowie die Kommentare zeigen ein gemischtes Stimmungsbild. Positiv hervorgehoben werden der Beitrag zu einer starken Gemeinschaft durch Austausch, das gemeinsame Erfahren, Erleben, Anregen und Lernen sowie die Förderung von Kultur für eine vielfältige Bevölkerung. Kritisch angemerkt wird, dass die Hürde, ins Theater zu gehen, für Nicht-Theatergänger weiterhin bestehen könnte und dass das Theater eher zu den Menschen kommen sollte (z.B. Workshops im Freien). Zudem wird befürchtet, dass vor allem bereits theateraffine Personen teilnehmen, Kinder ausgeschlossen bleiben und der Nutzen sehr spezifisch auf Teilnehmende begrenzt ist, ohne breitere Wirkungen wie Ausstellungen zu entfalten.",
      "qualitative_rationale_en": "Support for the project 'Mitmachen' (092) is moderate, with 3 out of 7 voters in favor. The mean score of -0.14 and the comments indicate a mixed sentiment. On the positive side, the project is seen as strengthening community through exchange, enabling shared experiences, inspiration and learning, and promoting culture for a diverse population. Critical remarks point out that the threshold for people who are not regular theatre-goers may remain high and that it might be more effective if the theatre went to the people (e.g. outdoor workshops). There are also concerns that mainly people already familiar with theatre would participate, that children cannot take part, and that the benefits are very specific to participants without broader impacts such as exhibitions.",
      "unified_explanation_de": "Das Projekt «Mitmachen» hat bei fast der Hälfte der Gruppe Anklang gefunden und wurde besonders dafür geschätzt, dass es Gemeinschaft stärkt, kulturelle Erfahrungen ermöglicht und Vielfalt im Theater sichtbar macht, auch wenn einige sich fragten, ob es noch offenere oder mobilere Formate bräuchte. Trotz seiner Unterstützerinnen und Unterstützer konnte das Projekt aufgrund des begrenzten Gesamtbudgets und anderer Prioritäten dieses Mal leider nicht realisiert werden.",
      "unified_explanation_en": "The project “Mitmachen” resonated with almost half of the group and was especially valued for strengthening community, enabling cultural experiences and embracing diversity in theatre, even though some people wondered whether it might need more open or mobile formats. Despite its supporters, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
