      "qualitative_rationale_de": "Das Projekt erzielt mit 6 von 7 Stimmen eine sehr hohe, nahezu einhellige Zustimmung. Die Kommentare betonen eine starke Gemeinschaft durch Austausch, spielerische Inklusion und den Mut zu einem überraschenden, mutigen Konzept, das vielfältige Menschen zusammenbringt. Es werden zentrale Bereiche des Förderkompasses abgedeckt: Personenvielfalt, Gemeinschaft durch Austausch sowie Erfahren, Erleben, Anregen und Lernen; einzig der Aspekt «Kultur in der Öffentlichkeit» wird als weniger stark vertreten wahrgenommen. Das Budget wird als plausibel eingeschätzt, mit dem Hinweis auf eine mögliche Kürzung um 20 % bei Unterstützung.",
      "qualitative_rationale_en": "The project receives very high, nearly unanimous support with 6 out of 7 votes. Comments highlight strong community building through exchange, playful inclusion, and the courage for a surprising, bold concept that brings together diverse people. It clearly addresses key areas of the funding compass: diversity of persons, community through exchange, and experiencing, learning, inspiring; only the aspect of “culture in public spaces” is seen as somewhat less prominent. The budget is considered plausible, with a note that a 20% reduction could be feasible if the project is funded.",
      "unified_explanation_de": "Das Projekt «Inklusive Trommelgruppe mit Gebärdensprache-Übersetzung» hat mit der Unterstützung von 6 von 7 Personen gezeigt, wie sehr die Idee einer spielerischen, inklusiven Kultur und der Austausch zwischen ganz unterschiedlichen Menschen in der Gemeinschaft Anklang findet. Trotz seiner vielen Unterstützerinnen und Unterstützer konnte das Projekt dieses Mal aufgrund des begrenzten Gesamtbudgets und anderer Prioritäten leider nicht realisiert werden.",
      "unified_explanation_en": "The project “Inclusive Drum Group with Sign Language Interpretation” clearly resonated with the community, with 6 out of 7 people supporting this playful and inclusive cultural idea that fosters exchange between very different people. Despite its many supporters, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
