      "Unified_Explanation_EN": "“Klangkartografien – hörbare Räume” received strong backing from the community, with 5 out of 7 people supporting it, even though some voters were still uncertain about parts of the concept and its concrete implementation. Despite its many supporters, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
      "Qualitative_Rationale_DE": "Die Zustimmung zum Projekt ist mit 5 von 7 Stimmen sehr hoch und zeigt eine deutlich positive Grundhaltung. Gleichzeitig deuten die Kommentare darauf hin, dass das Konzept von einigen noch als unausgereift und schwer vorstellbar wahrgenommen wird, insbesondere hinsichtlich der konkreten Umsetzung (Ablauf der Soundwalks, Art der Zugänglichkeit, Anzahl und Orte der Konzerte). Positiv hervorgehoben werden der spannende künstlerische Ansatz und die Tatsache, dass das Projekt im öffentlichen Raum stattfindet und vielen Menschen zugänglich ist. Insgesamt besteht starke inhaltliche Unterstützung, verbunden mit dem Wunsch nach klarerer Ausarbeitung und eventuell einer Reduktion des Budgets.",
      "Qualitative_Rationale_EN": "Support for the project is very high, with 5 out of 7 voters in favor, indicating a clearly positive overall attitude. At the same time, the comments suggest that some find the concept still underdeveloped and difficult to imagine in practice, especially regarding concrete implementation (how the sound walks work, how they are accessed, and the number and locations of concerts). On the positive side, the artistic approach is seen as exciting, and the fact that it takes place in public space and is accessible to many people is emphasized. Overall, there is strong substantive support, combined with a desire for a clearer project design and possibly a reduced budget.",
      "Algorithmic_Rationale_DE": "Das Projekt «Klangkartografien – hörbare Räume» (062) wurde von MES nicht gefördert. Die 5 Supporter:innen verfügten zusammen über ein Budget von 6652.81 CHF und konnten damit die benötigten 7500 CHF nicht decken.",
      "Algorithmic_Rationale_EN": "The project “Klangkartografien – hörbare Räume” (062) was not funded by MES. Its 5 supporters had a combined budget of 6652.81 CHF, which was not enough to cover the required 7500 CHF.",
