      "Qualitative_Rationale_EN": "The project 'Stab-Puppe Winterthur' (088) is supported by 2 out of 7 voters, indicating rather limited backing overall. The mean score of -1.00 confirms a generally skeptical sentiment. While there are some positive remarks, such as appreciation for the 'courage to surprise', the written feedback mainly highlights challenges: the need for several people to operate the puppet creates dependency and organizational hurdles, and there appear to be few suitable stages or platforms outside festival contexts. In addition, there is concern that the format—based on examples seen on YouTube—can quickly become boring. Overall, the tone towards the project is predominantly critical to hesitant.",
