      "Unified_Explanation_DE": "Der Laternenumzug wurde von 6 von 7 Personen unterstützt und zeigt damit sehr deutlich, wie stark die Idee einer gemeinsamen, kreativen und offenen Nachbarschaft mit Kultur im öffentlichen Raum in der Gemeinschaft verankert ist. Viele schätzten besonders, dass hier Menschen verschiedensten Alters und Hintergründen zusammenkommen können – ein kleines, kostengünstiges Projekt mit grosser Wirkung für Gemeinschaftsgefühl und Austausch.",
      "Unified_Explanation_EN": "The lantern parade was supported by 6 out of 7 people, clearly showing how strongly the idea of a shared, creative and open neighbourhood with culture in public space resonated with the community. Many especially appreciated that it brings together people of different ages and backgrounds – a small, low-cost project with a big impact on community spirit and exchange.",
      "Qualitative_Rationale_DE": "Das Projekt 'Laternenumzug' (095) stoesst auf eine sehr hohe, nahezu einhellige Zustimmung: 6 von 7 Personen unterstuetzen es. Die Kommentare heben besonders den kulturellen Wert in der Oeffentlichkeit, die Foerderung einer starken Gemeinschaft, den Mut zur Ueberraschung sowie die Moeglichkeit des Erfahrens, Erlebens, Anregens und Lernens hervor. Gelobt wird zudem, dass das Angebot unterschiedliche Personen zusammenbringt und durch das kreative Laternebauen wie auch den gemeinsamen Umzug Austausch und Gemeinschaftsgefuehl schafft. Positiv erwaehnt werden das stimmige, plausibel wirkende Budget und die Qualitaet des Projekts als 'klein aber fein'. Eine Stimme regt an, das Projekt in Zukunft groesser aufzuziehen und weist auf eine gewisse Einschraenkung bei der Unterstuetzung durch eine Einzelperson hin, ohne die insgesamt sehr positive Gesamtbewertung in Frage zu stellen.",
      "Qualitative_Rationale_EN": "The project 'Laternenumzug' (095) enjoys very high, nearly unanimous support: 6 out of 7 people back it. Comments particularly emphasize its cultural value in public space, the strengthening of community, encouragement of surprise and curiosity, and the potential for experiencing, inspiring, and learning. It is praised for bringing together diverse participants and fostering exchange and a sense of togetherness through creative lantern-making and the joint parade. The budget is viewed as coherent and plausible, and the project is described as 'small but fine'. One respondent suggests expanding the project in the future and notes some limitations due to it being run by an individual, but this does not undermine the overall very positive assessment.",
      "Algorithmic_Rationale_DE": "Ergebnis für 'Laternenumzug' (095): Das Projekt wurde vom MES finanziert. Es war kostengünstig und effizient (Wert: 380.00).",
      "Algorithmic_Rationale_EN": "Outcome for 'Laternenumzug' (095): The project was funded by MES. It was affordable and efficient (Value: 380.00).",
