      "Unified_Explanation_DE": "Kulturbegleitung OnThur fand mit 4 von 7 Stimmen deutlichen Rückhalt in der Gruppe und überzeugte viele mit seinem mutigen, stärkenden Ansatz für gelebte Inklusion. Trotz einzelner Fragen zu Zugänglichkeit für Kinder und Jugendliche sowie zur Höhe des Beitrags zeigte das Projekt, dass Kultur für unterschiedliche Menschen erfahrbar gemacht werden kann und darum eine starke Unterstützung verdient.",
      "Unified_Explanation_EN": "Kulturbegleitung OnThur received solid backing from the group, with 4 out of 7 people supporting it, and impressed many with its courageous, empowering approach to lived inclusion. Despite some open questions about access for children and young people and about the size of the grant, the project clearly showed how culture can be made accessible to diverse people and therefore earned strong support.",
      "Qualitative_Rationale_DE": "Das Projekt 'Kulturbegleitung OnThur' stösst mit 4 von 7 Stimmen auf eine klar positive, mehrheitlich zustimmende Resonanz. Die Kommentare betonen den mutigen und stärkenden Charakter des Angebots sowie den Beitrag zur gelebten Inklusion. Kritische Hinweise betreffen vor allem die eingeschränkte Teilnahmemöglichkeit für Kinder und Jugendliche, die zeitliche Ausrichtung auf Abendveranstaltungen sowie die als hoch empfundene beantragte Summe von 20'000 Franken für eine grössere Institution. Insgesamt überwiegt jedoch die positive Grundhaltung gegenüber dem Projekt deutlich.",
      "Qualitative_Rationale_EN": "The project 'Kulturbegleitung OnThur' receives clearly positive, majority support, with 4 out of 7 voters in favor. Comments highlight the project as courageous and empowering and emphasize its contribution to lived inclusion. Critical remarks focus mainly on limited participation options for children and young people, the scheduling primarily in the evening, and the perception that the requested amount of 20,000 francs is relatively high for a larger institution. Overall, the positive attitude toward the project clearly predominates.",
      "Algorithmic_Rationale_DE": "Outcome für 'Kulturbegleitung OnThur' (126): Das Projekt wurde durch MES finanziert. Es war erschwinglich und effizient (Wert: 2701.50).",
