      "Unified_Explanation_DE": "Mit 6 von 7 Stimmen hat das Projekt \"Vitodura zu Besuch\" deutlich gezeigt, wie stark es in der Gemeinschaft verankert ist und wie sehr die Idee eines szenischen Vortrags die Menschen berührt. Trotz einzelner Fragen – etwa zur Praesenz in der Oeffentlichkeit und zum Budget – hat das Projekt viele ueberzeugt, gerade weil es ein bestehendes Angebot sinnvoll erweitert und so noch mehr Menschen Zugang zu Wissen, Austausch und gemeinschaftlichen Erlebnissen ermoeglicht.",
      "Unified_Explanation_EN": "With 6 out of 7 votes, the project \"Vitodura zu Besuch\" clearly showed how strongly it resonated within the community and how much the idea of a scenic lecture touched people. Despite a few open questions – for example about its public presence and the budget – the project convinced many, especially because it meaningfully expands an existing offer and thus gives even more people access to knowledge, exchange, and shared experiences.",
      "Qualitative_Rationale_DE": "Das Projekt stösst auf sehr hohe, nahezu einhellige Zustimmung (6 von 7 Stimmen). Die Förderkriterien werden als gut erfüllt bewertet, insbesondere im Hinblick auf Gemeinschaft, Austausch und kulturelle Vielfalt. Positiv hervorgehoben wird, dass durch die Erweiterung eines bestehenden Projekts mehr Menschen Zugang zu den Inhalten erhalten. Leichte Vorbehalte betreffen primär den Aspekt «Kultur in der Öffentlichkeit», der bereits anderweitig stattfinde, sowie eine budgetäre Kürzung um 20 % aufgrund des guten Geschäftsergebnisses 2025 – grundsätzlich wird das Budget aber als in Ordnung angesehen.",
      "Qualitative_Rationale_EN": "The project enjoys very high, nearly unanimous support (6 out of 7 votes). The funding criteria are seen as well met, especially regarding community building, exchange, and cultural diversity. It is viewed positively that expanding an existing project will give more people access to the content. Minor reservations concern mainly the aspect of ‘culture in public spaces’, which is considered to be addressed elsewhere, as well as a proposed 20% budget reduction due to the good 2025 financial result – overall, however, the budget is regarded as acceptable.",
      "Algorithmic_Rationale_DE": "Das Projekt \"Vitodura zu Besuch\" - szenischer Vortrag (Arbeitstitel) wurde von MES gefoerdert. Es war kostenguenstig und effizient mit einem Projektwert von 1'999.75.",
