      "Unified_Explanation_DE": "Mit 4 von 7 Stimmen hat das Projekt spürbar Anklang gefunden und viele Menschen begeistert, weil es auf herzliche Weise Begegnung, Inklusion und gemeinsames Lernen in der Öffentlichkeit fördert. Trotz seiner vielen Unterstützerinnen und Unterstützer konnte das Projekt diesmal aufgrund des begrenzten Gesamtbudgets und anderer Prioritäten leider nicht realisiert werden.",
      "Unified_Explanation_EN": "With 4 out of 7 votes, the project clearly resonated and inspired many people by fostering warm encounters, inclusion, and shared learning in public spaces. Despite its many supporters, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
      "Qualitative_Rationale_DE": "Das Projekt erhält mit 4 von 7 Stimmen eine solide, mehrheitlich positive Unterstützung. Die Rückmeldungen betonen, dass alle Punkte des Förderkompasses abgedeckt werden: Kultur in der Öffentlichkeit, Stärkung der Gemeinschaft durch Austausch, Mut zur Überraschung sowie Erfahren, Erleben, Anregen und Lernen. Besonders hervorgehoben werden Inklusion, Vielfalt und das Zusammenbringen von Menschen, die gemeinsam Selbstwirksamkeit erleben. Insgesamt wird das Projekt als sehr bereichernd und horizonterweiternd wahrgenommen und zählt für einzelne Personen sogar zu ihren persönlichen Favoriten.",
      "Qualitative_Rationale_EN": "With 4 out of 7 votes, the project receives solid, clearly positive majority support. Feedback highlights that it addresses all key points of the funding compass: culture in public spaces, strengthening community through exchange, openness to surprise, as well as experiencing, inspiring, and learning. Inclusion, diversity, and bringing people together to experience a sense of agency are particularly emphasized. Overall, the project is seen as enriching and horizon-broadening, and for some individuals it even ranks among their personal favorites.",
      "Algorithmic_Rationale_DE": "Ergebnis für «Don't be Cool – be Warm!» (045): Das Projekt wurde vom MES nicht finanziert. Seine 4 Supporter hatten zusammen ein Budget von 11’939.00 CHF, was nicht ausreichte, um die 20’000 CHF zu decken.",
