      "Unified_Explanation_EN": "The project 'Slamstörung – Poetry Slam x Mental Health' resonated strongly with the group: 5 out of 7 people supported it and especially valued the open exchange, the sense of community, and the accessible way of addressing important mental health topics through poetry slam. Despite its many supporters, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
      "Qualitative_Rationale_DE": "Das Projekt stoesst mit 5 von 7 Stimmen auf sehr hohe, beinahe einhellige Zustimmung. Die Kommentierenden heben insbesondere die starke Gemeinschaft durch Austausch, den Mut zu Ueberraschungen, das Erfahren, Erleben, Anregen und Lernen sowie die kulturelle Offenheit fuer Personenvielfalt hervor. Positiv betont wird, dass wichtige mentale Gesundheitsthemen in zugänglicher Textform vermittelt werden und das Projekt als sinnvoll und wertvoll wahrgenommen wird. Kritisch angesprochen wird vor allem die finanzielle Barriere; es wird gewuenscht, dass die Teilnahme fuer alle Menschen finanziell moeglich sein sollte. Insgesamt ueberwiegt die klare, sehr positive Grundhaltung gegenueber dem Projekt, bei gleichzeitiger Sensibilitaet fuer Fragen der Zugänglichkeit und Finanzierung.",
      "Qualitative_Rationale_EN": "With 5 out of 7 votes, the project enjoys very high, almost unanimous support. Commenters particularly highlight the strong sense of community through exchange, the courage to surprise, opportunities to experience, learn and be inspired, as well as cultural openness to diverse participants. It is positively noted that important mental health topics are addressed in an accessible textual form, and the project is perceived as meaningful and valuable. The main point of criticism concerns the financial barrier; there is a wish that participation should be financially accessible to everyone. Overall, the sentiment is clearly and strongly positive, while also being attentive to issues of accessibility and funding.",
      "Algorithmic_Rationale_DE": "Das Projekt 'Slamstörung – Poetry Slam x Mental Health' (094) wurde von MES nicht finanziert. Die 5 Unterstuetzerinnen und Unterstuetzer verfuegten zusammen ueber ein Budget von 13’694.00 CHF, was nicht ausreichte, um die 18’300.00 CHF zu decken.",
