      "Unified_Explanation_EN": "Tatort Töss clearly resonated in the voting: 4 out of 7 people stood behind the idea with a substantial combined budget, supporting this interactive children’s crime story in public space that encourages reading, exploring, and shared family experiences. Despite this strong backing and many positive reactions to its focus on public culture, outdoor learning, and an element of surprise, the project unfortunately could not be realized this time due to the limited total budget and other priorities.",
      "Qualitative_Rationale_DE": "Die Zustimmung zum Projekt ist mit 4 von 7 Stimmen mehrheitlich positiv. Inhaltlich wird besonders gelobt, dass das Angebot im öffentlichen Raum stattfindet, Familien gemeinsam ein Abenteuer erleben können und Kinder zum Lesen, Erkunden und aktiven Erfahren im Freien angeregt werden. Mehrere Kommentare betonen den Bezug zu den Förderkompass-Kriterien (Kultur in der Öffentlichkeit, Mut zur Überraschung, Erfahren/Erleben/Anregen/Lernen) sowie die bewusste Gegenposition zu Konsum und Medienpassivität. Kritisch angemerkt werden die relativ spezifische Zielgruppe (Stadtteil Töss, Kinder um 10 Jahre) und die Umsetzung durch eine Einzelperson. Insgesamt überwiegt jedoch die positive Einschätzung; das Budget wird als plausibel beurteilt und ein Beitrag des Kulturkomitees als existenziell für die Realisierung betrachtet.",
      "Qualitative_Rationale_EN": "Support for the project is predominantly positive, with 4 out of 7 voters in favor. Commenters particularly praise that the offer takes place in public space, allows families to experience an adventure together, and encourages children to read, explore, and actively engage outdoors. Several remarks highlight the strong alignment with the funding compass criteria (culture in public space, courage to surprise, experiencing/learning/engaging) and appreciate the deliberate contrast to consumerism and passive media use by children. Critical points mention the relatively specific target group (district of Töss, children around 10 years old) and the fact that it is run by an individual. Overall, the positive assessment clearly prevails; the budget is considered plausible and a contribution from the cultural committee is seen as essential for implementation.",
      "Algorithmic_Rationale_DE": "Das Projekt «Tatort Töss – Ein interaktiver Kinderkrimi zum lesen, entdecken und ermitteln im Stadtraum Töss» (033) wurde von MES nicht finanziert. Die 4 Unterstuetzerinnen und Unterstuetzer verfuegten zusammen ueber ein Budget von 11’314.00 CHF und damit nicht genug, um die vorgesehenen 14’000 CHF zu decken.",
      "Algorithmic_Rationale_EN": "The project “Tatort Töss – An interactive children’s crime story to read, explore and investigate in the urban space of Töss” (033) was not funded by MES. Its 4 supporters had a combined budget of 11,314.00 CHF, which was not sufficient to cover the planned 14,000 CHF.",
