      "Unified_Explanation_EN": "The project “Kulturnacht geht raus | Die Stadt ist unsere Bühne” clearly resonated with the participants: a majority of voters saw it as an important contribution to culture in public space, accessible diversity, and encounters across all age groups. Despite this strong substantive support, the project unfortunately could not be realized this time due to the limited overall budget and other funding priorities.",
      "Qualitative_Rationale_DE": "Die Abstimmung zeigt mit 4 von 7 Stimmen eine solide Mehrheit zugunsten des Projekts. Die Kommentare heben besonders den niederschwelligen Zugang zu Kultur im öffentlichen Raum, die Vielfalt der angesprochenen Zielgruppen (von jung bis alt) und den Beitrag zu Austausch, Überraschung und gemeinschaftlichem Erleben hervor. Das Projekt wird als wichtig für Kultur in der Öffentlichkeit und für das Erfahren, Erleben, Anregen und Lernen bewertet. Vereinzelte Vorbehalte beziehen sich vor allem auf das im Verhältnis hohe Budget und die Frage, ob durch bereits zugesagte Mittel von Stadt, Kanton und Stiftungen eine zusätzliche Förderung noch nötig ist. Insgesamt überwiegt jedoch die positive Einschätzung, insbesondere wegen der breiten, inklusiven Wirkung im öffentlichen Raum.",
      "Qualitative_Rationale_EN": "The vote result, with 4 out of 7 voters in favor, indicates a clear majority support for the project. Comments particularly emphasize the low-threshold access to culture in public space, the diversity of target groups reached (from young to old), and the project’s contribution to exchange, surprise, and communal experiences. The project is seen as important for culture in public spaces and for experiencing, learning, and stimulating engagement. Some reservations focus mainly on the relatively large budget and the question of whether additional funding is necessary given existing commitments from the city, canton, and foundations. Overall, however, the positive assessment predominates, especially due to the broad and inclusive impact in public space.",
