      "Unified_Explanation_DE": "CREAcTION hat in der Gruppe spürbar Anklang gefunden: 3 von 7 Personen haben das Projekt unterstützt und besonders den sinnstiftenden, präventiven Charakter sowie die kulturelle Präsenz im öffentlichen Raum hervorgehoben, auch wenn Fragen zur Abgrenzung zwischen Kultur und Therapie sowie zur Höhe des Budgets offenblieben. Trotz dieser deutlichen Unterstützung konnte das Projekt aufgrund des limitierten Gesamtbudgets und anderer Prioritäten dieses Mal leider nicht realisiert werden.",
      "Unified_Explanation_EN": "CREAcTION clearly resonated within the group: 3 out of 7 people supported the project and especially valued its meaningful, preventive approach and its cultural visibility in public space, even though questions about the line between culture and therapy and about the size of the budget remained. Despite this solid support, the project unfortunately could not be realized this time due to the limited overall budget and other funding priorities.",
      "Qualitative_Rationale_DE": "Das Projekt 'CREAcTION' erhielt mit 3 von 7 Stimmen eine eher verhaltene Unterstützung. Die Kommentare betonen positiv, dass Kultur im öffentlichen Raum stattfindet, eine starke Gemeinschaft und kulturelle Vielfalt gefördert werden und das Projekt sinnstiftend sowie präventiv mit gesellschaftlichem Nutzen ist. Gleichzeitig gibt es kritische Nachfragen zur Abgrenzung zwischen Kulturprojekt und therapeutischem Ansatz, insbesondere weil im Gesuch erwähnt wird, dass Jugendliche angeleitet werden sollen, ihre Süchte zu überwinden. Zudem wird das Budget von 40'000 CHF als eher hoch beurteilt; vorgeschlagen wird eine Kürzung um rund 20 % bzw. eine Reduktion auf etwa 10'000–20'000 CHF, da das Projekt nach Ansicht einiger auch mit weniger Mitteln realisierbar wäre. Insgesamt überwiegt ein wohlwollend-positiver Grundton mit inhaltlichen Klärungsbedarfen und deutlicher Kritik an der Budgethöhe.",
      "Qualitative_Rationale_EN": "The project 'CREAcTION' received rather moderate support, with 3 out of 7 voters in favor. Comments highlight positively that it brings culture into public space, strengthens community, promotes cultural diversity, and is seen as meaningful and preventive with a clear benefit for society. At the same time, there are critical questions about the boundary between a cultural project and a therapeutic intervention, especially because the application states that young people will be guided in how to overcome their addictions. In addition, the budget of 40,000 CHF is viewed as relatively high; a reduction of around 20% or to roughly 10,000–20,000 CHF is suggested, as some believe the project could also work with fewer resources. Overall, the tone is generally appreciative and positive, but with a need for clarification on the therapeutic aspects and clear criticism of the requested budget level.",
      "Algorithmic_Rationale_DE": "Ergebnis für «CREAcTION» (136): Das Projekt wurde vom SBFI nicht finanziert. Die 3 Unterstützer hatten zusammen ein Budget von 7’313.50 CHF, was nicht ausreicht, um die benötigten 40’000 CHF zu decken.",
