      "Unified_Explanation_DE": "SubRock hat bei der Gruppe spürbar Anklang gefunden: 4 von 7 Personen haben das Projekt unterstuetzt und besonders die inklusive Idee mit Flyern in Blindenschrift geschätzt, auch wenn einzelne im Vergleich zu anderen Kulturprojekten noch mehr Ueberzeugungskraft erwarteten. Trotz dieser klaren Rueckendeckung aus der Community konnte das Projekt aufgrund des begrenzten Gesamtbudgets und anderer Prioritaeten dieses Mal leider nicht realisiert werden.",
      "Unified_Explanation_EN": "SubRock clearly resonated with the group: 4 out of 7 people supported the project and especially appreciated its inclusive idea of using flyers in Braille, even if some still felt other cultural projects were slightly more compelling. Despite this solid community backing, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
      "Qualitative_Rationale_DE": "Das Projekt 'SubRock' (007) erhaelt mit 4 von 7 Stimmen eine solide, insgesamt eher positive Unterstuetzung. Obwohl die durchschnittliche Punktzahl mit 0.14 eher verhalten ist, ueberwiegt die Zustimmung im Verhaeltnis zur Anzahl Stimmberechtigter. In den Rueckmeldungen wird positiv hervorgehoben, dass das Projekt gut zu den Foerderzielen wie 'Erfahren, Erleben, Anregen und Lernen' sowie 'Kultur fuer Personenvielfalt' passt. Besonders begruesst wird die geplante Barrierefreiheit durch gedruckte Flyer in Blindenschrift. Kritisch angemerkt wird, dass der Austausch zwischen Menschen nicht explizit thematisiert ist, wobei zugleich eingeräumt wird, dass dieser Austausch erfahrungsgemaess dennoch rund um Konzerte stattfindet. Insgesamt wird das Projekt im Bereich 'Kultur in der Oeffentlichkeit / Mut zur Ueberraschung' verortet. Der Hinweis, dass auch bei einer leichten Reduktion der Unterstuetzung (z.B. 20 % weniger Mittel) immer noch 6 von 7 geplanten Konzerten durchfuehrbar waeren, spricht dafuer, dass das Projekt als tragfaehig und foerderwuerdig angesehen wird, auch wenn vereinzelt der Vergleich zu „aehnlichen Kulturprojekten“ aufkommt, die teilweise noch staerker ueberzeugen.",
      "Qualitative_Rationale_EN": "The project 'SubRock' (007) receives a solid, overall rather positive level of support, with 4 out of 7 voters in favor. Although the mean score of 0.14 is relatively modest, the proportion of supporting votes is clearly positive relative to the voting group. Feedback highlights that the project aligns well with funding goals such as 'Experience, Discover, Inspire and Learn' and 'Culture for diverse audiences'. The planned accessibility measure of printed flyers in Braille is seen as a particular strength. A critical remark notes that interpersonal exchange is not explicitly mentioned, while also acknowledging that such exchange usually happens naturally around concerts. Overall, the project is placed in the field of 'Culture in public space / courage to surprise'. The comment that even with a slight reduction of support (e.g., 20% fewer resources) 6 of 7 concerts could still take place suggests that the project is considered viable and worthy of support, even if some comparable cultural projects are perceived as somewhat more compelling.",
      "Algorithmic_Rationale_DE": "Ergebnis für 'SubRock' (007): Das Projekt wurde vom MES NICHT finanziert. Seine 4 Supporter hatten zusammen ein Budget von 0.00 CHF und konnten damit die benötigten 7000 CHF nicht decken.",
      "Algorithmic_Rationale_EN": "Outcome for 'SubRock' (007): The project was NOT funded by MES. Its 4 supporters had a combined budget of 0.00 CHF, which was not enough to cover the required 7000 CHF.",
      "Vote_Ja": 1,
