      "Unified_Explanation_EN": "The project “Wald verbindet: Vielfalt erleben im Waldbad” inspired two community members to commit their budget to creating a vibrant and inclusive space for shared experiences in public. Despite this dedicated support and its strong alignment with the funding guidelines, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
      "Qualitative_Rationale_DE": "Die Zustimmung zum Projekt ist mit 2 von 7 Stimmen gering. Im Mittel wird es eher negativ bewertet (Durchschnittswert -0.71). Inhaltlich heben Befürworter hervor, dass das Projekt viele Aspekte des Förderkompasses vereint: Kultur in der Öffentlichkeit, Förderung einer starken Gemeinschaft durch Austausch sowie Erfahren, Erleben, Anregen und Lernen für eine vielfältige Teilnehmerschaft. Es wird auch als einfach umsetzbares Projekt mit kleinem Beitrag des Kulturkomitees gesehen. Kritische Stimmen bemängeln jedoch, dass das Angebot zu spezifisch bzw. auf Einzelpersonen zugeschnitten sei und primär nur die direkten Teilnehmenden profitieren würden, ohne breitere Wirkung etwa durch Ausstellungen.",
      "Qualitative_Rationale_EN": "Support for the project is low, with 2 out of 7 voters in favour. On average, it is rated rather negatively (mean score -0.71). Substantively, supporters emphasize that the project covers many aspects of the funding compass: culture in public space, fostering a strong community through exchange, and opportunities to experience, learn, and be inspired for a diverse group of participants. It is also seen as a simple project that could be implemented with a small contribution from the culture committee. Critical voices, however, argue that it is too specific or focused on individuals, benefiting mainly direct participants without broader impact, for example through exhibitions.",
      "Algorithmic_Rationale_DE": "Das Projekt \"Wald verbindet: Vielfalt erleben im Waldbad\" (018) wurde nicht vom MES unterstuetzt. Die beiden Unterstuetzer verfuegten zusammen ueber ein Budget von 473.00 CHF und konnten damit die erforderlichen 1820 CHF nicht decken.",
