      "Unified_Explanation_EN": "The project “Boomerang – everything comes back” persuaded two out of seven people with its bold, interactive concept and its strong focus on participation and exchange, while also sparking important questions around inclusion, accessibility and concrete implementation. Despite this support and genuine interest in the content, the project unfortunately could not be realized this time due to the limited overall budget and other priorities.",
      "Qualitative_Rationale_DE": "Die Zustimmung zum Projekt ist mit 2 von 7 Stimmen gering. Die durchschnittliche Bewertung von -0.57 weist auf eine eher kritische Gesamtstimmung hin. Positiv hervorgehoben werden der interaktive und mutige Ansatz sowie die Partizipationsmoeglichkeit des Publikums an der Entstehung des Theaterstuecks. Kritisch gesehen werden jedoch Fragen der Inklusion (insbesondere fuer Kinder und gehoerlose Menschen), der Zugänglichkeit (kein zufaelliger Kontakt mit dem Projekt), sowie Unklarheiten zum konkreten Ablauf und Mehrwert der Interaktion (Anzahl Lesungen, was genau ‚zurueckkommt‘). Auch die Hohe des Betrags im Verhaeltnis zur Eigenleistung der Autoren wird hinterfragt. Insgesamt ueberwiegt eine skeptische bis kritische Haltung trotz inhaltlich grundsaetzlichem Interesse am Thema und Format.",
      "Qualitative_Rationale_EN": "Support for the project is low, with 2 out of 7 voters in favor. The mean score of -0.57 indicates an overall rather critical sentiment. On the positive side, the project is praised as interactive and bold, and the audience participation in creating the theatre piece is valued. However, concerns are raised about inclusion (especially for children and deaf people), accessibility (no chance encounters with the project), and a lack of clarity about the concrete process and added value of the interaction (number of readings, what exactly ‘comes back’ from the audience). The requested budget is also questioned in relation to the authors’ own contribution. Overall, the mood is more skeptical to critical, despite a basic interest in the topic and format.",
      "Algorithmic_Rationale_DE": "Ergebnis für «Boomerang 'alles kommt zurück'» (116): Das Projekt wurde NICHT vom MES finanziert. Seine 2 Unterstützer hatten zusammen ein Budget von 0.00 CHF und konnten damit die benötigten 9600 CHF nicht decken.",
