      "Qualitative_Rationale_DE": "Die Zustimmung fuer das Projekt ist mit 1 von 7 Stimmen insgesamt sehr gering und spiegelt sich auch im negativen Durchschnittsscore (-1.29) wider. Inhaltlich wird positiv hervorgehoben, dass ein wichtiges Tabuthema (Tod) mutig, humorvoll und anregend aufgegriffen wird und dass der Ansatz gut zum Foerderkompass (Austausch, Lernen, Ueberraschung) passt. Kritisch sehen die Bewertenden vor allem die hohen Gagen beziehungsweise die starke Fokussierung auf prominente Gaeste, den hohen Aufwand bzw. Preis fuer einen einzelnen Abend sowie Zweifel, ob echter Austausch waehrend einer Talkshow im geschlossenen Raum stattfinden kann oder eher nur im Anschluss. Insgesamt ueberwiegt eine skeptische, eher ablehnende Grundhaltung trotz Anerkennung des thematischen Werts und der professionellen Umsetzung.",
      "Qualitative_Rationale_EN": "Support for the project is very low, with only 1 out of 7 voters in favor, and this is reflected in the negative mean score (-1.29). On the positive side, reviewers emphasize that the project addresses an important taboo topic (death) in a bold, humorous, and stimulating way, and that it fits well with the funding guidelines (exchange, learning, surprise). However, they criticize in particular the high fees for the celebrities and the strong focus on prominent guests, the relatively high cost for a single evening, and doubts about whether genuine exchange can really take place during a talk show in a closed venue or only afterward. Overall, the sentiment is skeptical and rather negative, despite recognition of the thematic relevance and professional implementation.",
      "Algorithmic_Rationale_DE": "Das Projekt 'BLIND DATE mit dem Tod - Eine Talkshow' (076) wurde nicht vom MES finanziert. Die 1 Unterstuetzerin bzw. der 1 Unterstuetzer verfuegte zusammen ueber ein Budget von 473.00 CHF, was nicht ausreichte, um die erforderlichen 29_700 CHF zu decken.",
